<script setup lang="ts">import { Head } from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import type { Property } from '@/types'; import { onMounted, ref } from 'vue'; const items=ref<Property[]>([]); onMounted(()=>items.value=JSON.parse(localStorage.getItem('nova_compare')||'[]')); const remove=(id:number)=>{items.value=items.value.filter(i=>i.id!==id);localStorage.setItem('nova_compare',JSON.stringify(items.value))}; const money=(v:string|number)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(v));</script>
<template><Head title="Сравнение объектов"/><AppLayout><section class="section"><div class="container-page"><div class="eyebrow">До четырёх объектов</div><h1 class="mt-3 text-5xl">Сравнение</h1><div v-if="!items.length" class="card mt-10 p-14 text-center"><h2 class="text-3xl">Список сравнения пуст</h2><p class="mt-3 text-stone-500">Добавьте объекты из каталога, чтобы увидеть различия.</p><a href="/properties" class="btn btn-primary mt-6">Перейти в каталог</a></div><div v-else class="mt-10 overflow-x-auto"><table class="w-full min-w-[760px] border-collapse bg-white text-left"><thead><tr><th class="border p-4">Характеристика</th><th v-for="item in items" class="border p-4 align-top"><img :src="item.cover_url" :alt="item.title" class="mb-3 h-32 w-full rounded-lg object-cover"><a :href="`/properties/${item.slug}`" class="serif text-lg">{{ item.title }}</a><button class="mt-2 block text-xs font-bold text-red-700" @click="remove(item.id)">Убрать</button></th></tr></thead><tbody><tr><th class="border bg-stone-50 p-4">Цена</th><td v-for="item in items" class="border p-4 font-bold text-[#174c43]">${{ money(item.price) }}</td></tr><tr><th class="border bg-stone-50 p-4">Тип сделки</th><td v-for="item in items" class="border p-4">{{ item.operation==='sale'?'Продажа':'Аренда' }}</td></tr><tr><th class="border bg-stone-50 p-4">Площадь</th><td v-for="item in items" class="border p-4">{{ item.area }} м²</td></tr><tr><th class="border bg-stone-50 p-4">Комнаты</th><td v-for="item in items" class="border p-4">{{ item.rooms||'—' }}</td></tr><tr><th class="border bg-stone-50 p-4">Район</th><td v-for="item in items" class="border p-4">{{ item.district }}</td></tr><tr><th class="border bg-stone-50 p-4">Этаж</th><td v-for="item in items" class="border p-4">{{ item.floor||'—' }} / {{ item.total_floors||'—' }}</td></tr></tbody></table></div></div></section></AppLayout></template>
